INSERT INTO edu_course (code,name,age_min,age_max,direction,level,description,objectives,outcomes,cover_url,status,version,revision,lessons_json,tenant_id) SELECT 'STORY-08','互动故事创作','8','10','STORY','BEGINNER','面向8—10岁孩子，通过八次创作完成一个能选择分支、检查结局并分享的原创故事。课堂在电脑与外部课堂工具中进行；此内容为待教师审定的课程草案。','能够描述问题、拆分任务、用AI协助创作、独立检查结果并表达修改理由。','一个能选择分支、检查结局并分享的原创故事','','DRAFT','0','1','[{"sort":1,"title":"我的故事地图","durationMinutes":90,"objectives":"理解人物、目标与情节，能够画出两条故事路线。","concept":"人物、目标与情节","task":"画出两条故事路线","aiUse":"先自己描述目标，再请AI提出小步骤；逐段阅读建议，不提交姓名、住址或账号密钥。","checkMethod":"预测运行结果，至少验证一个正常场景和一个失败或边界场景；保留修改前后的证据。","materials":"电脑、教师准备的测试环境、原创或已获授权素材。","assignment":"完成“画出两条故事路线”，提交作品或截图、两条测试记录，以及自己解释的一处修改。","rubric":"任务完成度40%；解释与核验30%；独立修改20%；表达与协作10%。"},{"sort":2,"title":"让角色说话","durationMinutes":90,"objectives":"理解对话与事件，能够用点击推动一次对话。","concept":"对话与事件","task":"用点击推动一次对话","aiUse":"先自己描述目标，再请AI提出小步骤；逐段阅读建议，不提交姓名、住址或账号密钥。","checkMethod":"预测运行结果，至少验证一个正常场景和一个失败或边界场景；保留修改前后的证据。","materials":"电脑、教师准备的测试环境、原创或已获授权素材。","assignment":"完成“用点击推动一次对话”，提交作品或截图、两条测试记录，以及自己解释的一处修改。","rubric":"任务完成度40%；解释与核验30%；独立修改20%；表达与协作10%。"},{"sort":3,"title":"选择改变故事","durationMinutes":90,"objectives":"理解条件与分支，能够建立两个可选择的决定。","concept":"条件与分支","task":"建立两个可选择的决定","aiUse":"先自己描述目标，再请AI提出小步骤；逐段阅读建议，不提交姓名、住址或账号密钥。","checkMethod":"预测运行结果，至少验证一个正常场景和一个失败或边界场景；保留修改前后的证据。","materials":"电脑、教师准备的测试环境、原创或已获授权素材。","assignment":"完成“建立两个可选择的决定”，提交作品或截图、两条测试记录，以及自己解释的一处修改。","rubric":"任务完成度40%；解释与核验30%；独立修改20%；表达与协作10%。"},{"sort":4,"title":"记住你的选择","durationMinutes":90,"objectives":"理解变量与状态，能够让早先选择影响后续情节。","concept":"变量与状态","task":"让早先选择影响后续情节","aiUse":"先自己描述目标，再请AI提出小步骤；逐段阅读建议，不提交姓名、住址或账号密钥。","checkMethod":"预测运行结果，至少验证一个正常场景和一个失败或边界场景；保留修改前后的证据。","materials":"电脑、教师准备的测试环境、原创或已获授权素材。","assignment":"完成“让早先选择影响后续情节”，提交作品或截图、两条测试记录，以及自己解释的一处修改。","rubric":"任务完成度40%；解释与核验30%；独立修改20%；表达与协作10%。"},{"sort":5,"title":"给故事加声音","durationMinutes":90,"objectives":"理解媒体与资源授权，能够制作自己的声音和背景。","concept":"媒体与资源授权","task":"制作自己的声音和背景","aiUse":"先自己描述目标，再请AI